+        `[Error: Expected string literal summary, received JSXExpressionContainer]`
+      );
+    });
+  });
+
+  describe('isTemplate', () => {
+    it('boolean implicit', async () => {
+      const input = dedent`
+        <Meta isTemplate />
+      `;
+      await expect(analyze(input)).resolves.toMatchInlineSnapshot(`
+        {
+          "imports": [],
+          "isTemplate": true,
+          "metaTags": undefined,
+          "name": undefined,
+          "of": undefined,
+          "summary": undefined,
+          "title": undefined,
